export type SseDataHandler = (data: string) => void;

export class StreamingUnavailableError extends Error {
	constructor(message: string) {
		super(message);
		this.name = "StreamingUnavailableError";
	}
}

export function canUseFetchStreaming(): boolean {
	return typeof globalThis.fetch === "function"
		&& typeof ReadableStream !== "undefined"
		&& typeof TextDecoder !== "undefined";
}

export async function readFetchSseStream(response: Response, onData: SseDataHandler): Promise<void> {
	const body = response.body;
	if (!body) {
		throw new StreamingUnavailableError("Streaming is not available in this environment.");
	}

	const reader = body.getReader();
	const decoder = new TextDecoder();
	let buffer = "";

	try {
		while (true) {
			const result = await reader.read();
			if (result.done) {
				break;
			}

			buffer += decoder.decode(result.value, { stream: true });
			const consumed = consumeSseFrames(buffer);
			buffer = consumed.rest;
			for (const frame of consumed.frames) {
				emitSseFrame(frame, onData);
			}
		}
	} finally {
		reader.releaseLock();
	}

	buffer += decoder.decode();
	if (buffer.trim()) {
		emitSseFrame(buffer, onData);
	}
}

export function consumeSseFrames(buffer: string): { frames: string[]; rest: string } {
	const normalized = buffer.replace(/\r\n/gu, "\n");
	const parts = normalized.split("\n\n");
	return {
		frames: parts.slice(0, -1),
		rest: parts[parts.length - 1] ?? "",
	};
}

export function extractSseData(frame: string): string | null {
	const data = frame
		.split(/\r?\n/u)
		.filter((line) => line.startsWith("data:"))
		.map((line) => line.slice(5).trimStart())
		.join("\n");

	return data || null;
}

function emitSseFrame(frame: string, onData: SseDataHandler): void {
	const data = extractSseData(frame);
	if (data) {
		onData(data);
	}
}

import {
	getValidCodexAuth,
	refreshCodexAuth,
} from "./codex-auth";
import { CodexRequestError, requestCodexText } from "./codex-client";
import { OLLAMA_CLOUD_BASE_URL } from "./ollama-cloud";
import { DocumentProcessingSettings } from "../settings-data";
import { translate } from "../i18n";
import { OpenAiRequestError, requestOpenAiText } from "./openai-client";

const TEST_PROMPT = "Reply with exactly: ok";

export interface LlmCheckResult {
	ok: boolean;
	provider: string;
	model: string;
	message: string;
	latencyMs: number;
	output: string;
}

export async function checkLlmConnection(
	settings: DocumentProcessingSettings,
	saveSettings: () => Promise<void>,
): Promise<LlmCheckResult> {
	if (settings.llmProvider === "codex-login") {
		return checkCodexLogin(settings, saveSettings);
	}

	if (settings.llmProvider === "ollama-cloud") {
		return checkApiKeyProvider(settings, {
			apiKey: settings.ollamaApiKey,
			baseUrl: OLLAMA_CLOUD_BASE_URL,
			model: settings.ollamaModel,
			providerLabel: translate(settings.language, "provider.ollamaCloud"),
			missingKeyError: translate(settings.language, "check.error.missingOllamaKey"),
			missingModelError: translate(settings.language, "check.error.missingOllamaModel"),
			maxOutputTokens: 256,
		});
	}

	return checkApiKeyProvider(settings, {
		apiKey: settings.openaiApiKey,
		baseUrl: settings.openaiBaseUrl,
		model: settings.openaiModel,
		providerLabel: translate(settings.language, "provider.openaiApi"),
		missingKeyError: translate(settings.language, "check.error.missingApiKey"),
		missingModelError: translate(settings.language, "check.error.missingOpenAiModel"),
		maxOutputTokens: 16,
	});
}

interface ApiKeyCheckConfig {
	apiKey: string;
	baseUrl: string;
	model: string;
	providerLabel: string;
	missingKeyError: string;
	missingModelError: string;
	maxOutputTokens: number;
}

async function checkApiKeyProvider(settings: DocumentProcessingSettings, config: ApiKeyCheckConfig): Promise<LlmCheckResult> {
	const apiKey = config.apiKey.trim();
	const model = config.model.trim();

	if (!apiKey) {
		throw new Error(config.missingKeyError);
	}

	if (!model) {
		throw new Error(config.missingModelError);
	}

	const startedAt = Date.now();
	try {
		const response = await requestOpenAiText({
			apiKey,
			baseUrl: config.baseUrl,
			model,
			prompt: TEST_PROMPT,
			maxOutputTokens: config.maxOutputTokens,
		});
		return buildResult(config.providerLabel, model, response.text, Date.now() - startedAt, settings);
	} catch (error) {
		if (error instanceof OpenAiRequestError) {
			throw new Error(formatOpenAiError(error.status, error.payload, settings));
		}

		throw error;
	}
}

async function checkCodexLogin(
	settings: DocumentProcessingSettings,
	saveSettings: () => Promise<void>,
): Promise<LlmCheckResult> {
	const model = settings.codexModel.trim();

	if (!model) {
		throw new Error(translate(settings.language, "check.error.missingCodexModel"));
	}

	if (!settings.codexAuth) {
		throw new Error(translate(settings.language, "check.error.notSignedIn"));
	}

	const auth = await getCodexAuthForCheck(settings, saveSettings);
	const startedAt = Date.now();
	const requestOptions = {
		reasoningEffort: settings.codexReasoningEffort,
		serviceTier: settings.codexServiceTier,
	};

	try {
		const output = await requestCodexText(model, TEST_PROMPT, auth, requestOptions);
		return buildResult(translate(settings.language, "provider.codexLogin"), model, output.text, Date.now() - startedAt, settings);
	} catch (error) {
		if (!(error instanceof CodexRequestError) || error.status !== 401) {
			if (error instanceof CodexRequestError) {
				throw new Error(translate(settings.language, "check.error.modelHttp", {
					status: error.status,
					message: cleanCodexRequestMessage(error.message),
				}));
			}

			throw error;
		}

		const refreshed = await refreshCodexAuth(auth);
		settings.codexAuth = refreshed;
		await saveSettings();
		const output = await requestCodexText(model, TEST_PROMPT, refreshed, requestOptions);
		return buildResult(translate(settings.language, "provider.codexLogin"), model, output.text, Date.now() - startedAt, settings);
	}
}

async function getCodexAuthForCheck(
	settings: DocumentProcessingSettings,
	saveSettings: () => Promise<void>,
) {
	try {
		return await getValidCodexAuth(settings, saveSettings);
	} catch (error) {
		console.error("Document Processing account check failed", error);
		throw new Error(translate(settings.language, "check.error.signInUnavailable"));
	}
}

function cleanCodexRequestMessage(message: string): string {
	return message.replace(/^Codex request failed with HTTP \d+:\s*/u, "");
}

function formatOpenAiError(status: number, payload: { error?: { message?: string; code?: string } }, settings: DocumentProcessingSettings): string {
	const error = payload.error;
	const message = error?.message ?? translate(settings.language, "check.error.openAiDefault");
	const code = error?.code ? ` (${error.code})` : "";
	return translate(settings.language, "check.error.openAiHttp", { status, code, message });
}

function buildResult(
	provider: string,
	model: string,
	output: string,
	latencyMs: number,
	settings: DocumentProcessingSettings,
): LlmCheckResult {
	const normalizedOutput = output.trim();
	const ok = /^ok[.!]?$/i.test(normalizedOutput);

	if (!ok) {
		throw new Error(translate(settings.language, "check.error.unexpectedOutput", {
			provider,
			output: normalizedOutput || translate(settings.language, "check.emptyOutput"),
		}));
	}

	return {
		ok,
		provider,
		model,
		message: translate(settings.language, "check.success", { provider, model, latency: latencyMs }),
		latencyMs,
		output: normalizedOutput,
	};
}

export function parseLlmJsonObject(rawText: string): unknown {
	const trimmed = rawText.trim();
	const unwrapped = unwrapCodeFence(trimmed);

	try {
		return JSON.parse(unwrapped);
	} catch {
		const start = unwrapped.indexOf("{");
		const end = unwrapped.lastIndexOf("}");
		if (start < 0 || end <= start) {
			throw new Error("LLM output is not valid JSON.");
		}

		return JSON.parse(unwrapped.slice(start, end + 1));
	}
}

export function normalizeChangeSummary(value: unknown, maxItems = 8): string[] {
	if (typeof value === "string" && value.trim()) {
		return [value.trim()];
	}

	if (!Array.isArray(value)) {
		return [];
	}

	return value
		.filter((item): item is string => typeof item === "string" && item.trim().length > 0)
		.map((item) => item.trim())
		.slice(0, maxItems);
}

function unwrapCodeFence(value: string): string {
	const fenceMatch = /^```(?:json)?\s*([\s\S]*?)\s*```$/iu.exec(value);
	return fenceMatch?.[1] ?? value;
}

export type LlmProgressPhase = "uploading" | "waiting" | "streaming" | "completed";

export interface LlmTokenUsage {
	inputTokens: number;
	outputTokens: number;
	totalTokens?: number;
	inputTokensEstimated: boolean;
	outputTokensEstimated: boolean;
}

export interface LlmProgressUpdate extends LlmTokenUsage {
	phase: LlmProgressPhase;
}

export type LlmProgressCallback = (progress: LlmProgressUpdate) => void;

export interface ApiUsagePayload {
	input_tokens?: number;
	output_tokens?: number;
	total_tokens?: number;
}

export function estimateTokens(text: string): number {
	const trimmed = text.trim();
	if (!trimmed) {
		return 0;
	}

	let cjkCharacters = 0;
	let otherCharacters = 0;
	for (const character of trimmed) {
		if (/[\u3040-\u30ff\u3400-\u9fff\uf900-\ufaff]/u.test(character)) {
			cjkCharacters += 1;
		} else if (!/\s/u.test(character)) {
			otherCharacters += 1;
		}
	}

	return Math.max(1, Math.ceil(cjkCharacters + (otherCharacters / 4)));
}

export function estimateInputTokens(instructions: string | undefined, prompt: string): number {
	return estimateTokens(`${instructions ?? ""}\n\n${prompt}`);
}

export function buildEstimatedUsage(inputTokens: number, outputText: string): LlmTokenUsage {
	const outputTokens = estimateTokens(outputText);
	return {
		inputTokens,
		outputTokens,
		totalTokens: inputTokens + outputTokens,
		inputTokensEstimated: true,
		outputTokensEstimated: true,
	};
}

export function usageFromApi(payload: ApiUsagePayload | undefined): LlmTokenUsage | undefined {
	const rawInputTokens = payload?.input_tokens;
	const rawOutputTokens = payload?.output_tokens;
	const rawTotalTokens = payload?.total_tokens;

	if (
		typeof rawInputTokens !== "number"
		|| typeof rawOutputTokens !== "number"
		|| !Number.isFinite(rawInputTokens)
		|| !Number.isFinite(rawOutputTokens)
	) {
		return undefined;
	}

	const inputTokens = Math.max(0, Math.round(rawInputTokens));
	const outputTokens = Math.max(0, Math.round(rawOutputTokens));
	const totalTokens = typeof rawTotalTokens === "number" && Number.isFinite(rawTotalTokens)
		? Math.max(0, Math.round(rawTotalTokens))
		: inputTokens + outputTokens;

	return {
		inputTokens,
		outputTokens,
		totalTokens,
		inputTokensEstimated: false,
		outputTokensEstimated: false,
	};
}

export function buildProgress(
	phase: LlmProgressPhase,
	inputTokens: number,
	outputText: string,
	usage?: LlmTokenUsage,
): LlmProgressUpdate {
	if (usage) {
		return {
			...usage,
			phase,
		};
	}

	return {
		...buildEstimatedUsage(inputTokens, outputText),
		phase,
	};
}

import { requestUrl } from "obsidian";
import { isAbortError, LLM_CANCELED_MESSAGE, throwIfAborted } from "./abort";
import { extractResponsesOutputText, ResponsesOutputPayload } from "./responses-payload";
import { canUseFetchStreaming, readFetchSseStream, StreamingUnavailableError } from "./sse";
import {
	ApiUsagePayload,
	buildEstimatedUsage,
	buildProgress,
	estimateInputTokens,
	LlmProgressCallback,
	LlmTokenUsage,
	usageFromApi,
} from "./token-usage";

export const DEFAULT_OPENAI_BASE_URL = "https://api.openai.com/v1";

interface OpenAiErrorPayload {
	error?: {
		message?: string;
		type?: string;
		code?: string;
	};
}

type OpenAiResponsePayload = OpenAiErrorPayload & ResponsesOutputPayload;

interface OpenAiStreamPayload extends OpenAiResponsePayload {
	type?: string;
	delta?: string;
	response?: OpenAiResponsePayload;
	item?: {
		content?: Array<{
			text?: string;
			type?: string;
		}>;
	};
}

interface OpenAiChatCompletionPayload extends OpenAiErrorPayload {
	choices?: Array<{
		message?: {
			content?: string | Array<{
				text?: string;
				type?: string;
			}>;
		};
	}>;
	usage?: ApiUsagePayload;
}

export interface OpenAiTextRequest {
	apiKey: string;
	baseUrl?: string;
	model: string;
	prompt: string;
	instructions?: string;
	maxOutputTokens?: number;
	onProgress?: LlmProgressCallback;
	signal?: AbortSignal;
}

export interface OpenAiTextResponse {
	text: string;
	usage: LlmTokenUsage;
}

export class OpenAiRequestError extends Error {
	status: number;
	payload: OpenAiErrorPayload;

	constructor(status: number, message: string, payload: OpenAiErrorPayload) {
		super(message);
		this.name = "OpenAiRequestError";
		this.status = status;
		this.payload = payload;
	}
}

export async function requestOpenAiText(request: OpenAiTextRequest): Promise<OpenAiTextResponse> {
	throwIfAborted(request.signal);
	const inputTokens = estimateInputTokens(request.instructions, request.prompt);
	request.onProgress?.({
		...buildEstimatedUsage(inputTokens, ""),
		phase: "uploading",
	});

	if (!shouldUseResponsesApi(request.baseUrl)) {
		return requestOpenAiChatCompletionsBuffered(request, inputTokens);
	}

	if (request.onProgress && canUseFetchStreaming()) {
		try {
			return await requestOpenAiTextStreaming(request, inputTokens);
		} catch (error) {
			if (!(error instanceof StreamingUnavailableError)) {
				throw error;
			}
		}
	}

	return requestOpenAiTextBuffered(request, inputTokens);
}

async function requestOpenAiChatCompletionsBuffered(request: OpenAiTextRequest, inputTokens: number): Promise<OpenAiTextResponse> {
	throwIfAborted(request.signal);
	request.onProgress?.({
		...buildEstimatedUsage(inputTokens, ""),
		phase: "waiting",
	});

	const response = await requestUrl({
		url: buildOpenAiApiUrl(request.baseUrl, "chat/completions"),
		method: "POST",
		contentType: "application/json",
		headers: {
			Authorization: `Bearer ${request.apiKey}`,
		},
		body: JSON.stringify({
			model: request.model,
			messages: buildChatCompletionMessages(request),
			max_tokens: request.maxOutputTokens,
		}),
		throw: false,
	});
	throwIfAborted(request.signal);
	const payload = response.json as OpenAiChatCompletionPayload;

	if (response.status < 200 || response.status >= 300) {
		throw new OpenAiRequestError(response.status, formatOpenAiError(response.status, payload), payload);
	}

	const text = extractChatCompletionText(payload);
	const usage = usageFromApi(payload.usage) ?? buildEstimatedUsage(inputTokens, text);
	request.onProgress?.(buildProgress("completed", inputTokens, text, usage));

	return {
		text,
		usage,
	};
}

async function requestOpenAiTextBuffered(request: OpenAiTextRequest, inputTokens: number): Promise<OpenAiTextResponse> {
	throwIfAborted(request.signal);
	request.onProgress?.({
		...buildEstimatedUsage(inputTokens, ""),
		phase: "waiting",
	});

	const response = await requestUrl({
		url: buildOpenAiApiUrl(request.baseUrl, "responses"),
		method: "POST",
		contentType: "application/json",
		headers: {
			Authorization: `Bearer ${request.apiKey}`,
		},
		body: JSON.stringify({
			model: request.model,
			instructions: request.instructions,
			input: request.prompt,
			max_output_tokens: request.maxOutputTokens,
			store: false,
		}),
		throw: false,
	});
	throwIfAborted(request.signal);
	const payload = response.json as OpenAiResponsePayload;

	if (response.status < 200 || response.status >= 300) {
		throw new OpenAiRequestError(response.status, formatOpenAiError(response.status, payload), payload);
	}

	const text = extractResponsesOutputText(payload);
	const usage = usageFromApi(payload.usage) ?? buildEstimatedUsage(inputTokens, text);
	request.onProgress?.(buildProgress("completed", inputTokens, text, usage));

	return {
		text,
		usage,
	};
}

async function requestOpenAiTextStreaming(request: OpenAiTextRequest, inputTokens: number): Promise<OpenAiTextResponse> {
	let response: Response;
	try {
		response = await globalThis.fetch(buildOpenAiApiUrl(request.baseUrl, "responses"), {
			method: "POST",
			headers: {
				Accept: "text/event-stream",
				Authorization: `Bearer ${request.apiKey}`,
				"Content-Type": "application/json",
			},
			body: JSON.stringify({
				model: request.model,
				instructions: request.instructions,
				input: request.prompt,
				max_output_tokens: request.maxOutputTokens,
				store: false,
				stream: true,
			}),
			signal: request.signal,
		});
	} catch (error) {
		if (isAbortError(error) || request.signal?.aborted) {
			throw new Error(LLM_CANCELED_MESSAGE);
		}

		throw new StreamingUnavailableError(error instanceof Error ? error.message : "Streaming request failed.");
	}

	if (!response.ok) {
		const errorText = await response.text();
		const payload = parseOpenAiErrorPayload(errorText);
		throw new OpenAiRequestError(response.status, formatOpenAiError(response.status, payload), payload);
	}

	let streamedText = "";
	let completedText = "";
	let usage: LlmTokenUsage | undefined;

	await readFetchSseStream(response, (data) => {
		throwIfAborted(request.signal);
		if (data === "[DONE]") {
			return;
		}

		const payload = JSON.parse(data) as OpenAiStreamPayload;
		const error = payload.error;
		if (error?.message) {
			throw new OpenAiRequestError(response.status, error.message, payload);
		}

		const delta = extractOpenAiStreamDelta(payload);
		if (delta) {
			streamedText += delta;
			request.onProgress?.(buildProgress("streaming", inputTokens, streamedText));
		}

		const responseText = payload.response ? extractResponsesOutputText(payload.response) : "";
		if (responseText) {
			completedText = responseText;
		}

		usage = usageFromApi(payload.response?.usage ?? payload.usage) ?? usage;
	});

	const text = completedText || streamedText;
	throwIfAborted(request.signal);
	const finalUsage = usage ?? buildEstimatedUsage(inputTokens, text);
	request.onProgress?.(buildProgress("completed", inputTokens, text, finalUsage));

	return {
		text,
		usage: finalUsage,
	};
}

export function normalizeOpenAiBaseUrl(value: string | undefined): string {
	const rawValue = value?.trim() || DEFAULT_OPENAI_BASE_URL;
	const withProtocol = /^[a-z][a-z0-9+.-]*:\/\//iu.test(rawValue)
		? rawValue
		: `https://${rawValue}`;
	const url = new URL(withProtocol);
	url.hash = "";
	url.search = "";

	const pathParts = url.pathname.split("/").filter(Boolean);
	const lastPart = pathParts[pathParts.length - 1];
	if (lastPart === "responses" || lastPart === "models" || lastPart === "completions") {
		pathParts.pop();
	}

	if (pathParts[pathParts.length - 1] === "chat") {
		pathParts.pop();
	}

	url.pathname = pathParts.length ? `/${pathParts.join("/")}` : "";
	return url.toString().replace(/\/$/u, "");
}

export function buildOpenAiApiUrl(baseUrl: string | undefined, path: string): string {
	const normalizedBaseUrl = normalizeOpenAiBaseUrl(baseUrl);
	return `${normalizedBaseUrl}/${path.replace(/^\/+/u, "")}`;
}

export function shouldUseResponsesApi(baseUrl: string | undefined): boolean {
	return normalizeOpenAiBaseUrl(baseUrl) === DEFAULT_OPENAI_BASE_URL;
}

function buildChatCompletionMessages(request: OpenAiTextRequest): Array<{ role: "system" | "user"; content: string }> {
	const messages: Array<{ role: "system" | "user"; content: string }> = [];
	if (request.instructions?.trim()) {
		messages.push({ role: "system", content: request.instructions.trim() });
	}

	messages.push({ role: "user", content: request.prompt });
	return messages;
}

function formatOpenAiError(status: number, payload: OpenAiErrorPayload): string {
	const message = payload.error?.message ?? "The OpenAI API returned an error.";
	const code = payload.error?.code ? ` (${payload.error.code})` : "";
	return `OpenAI API request failed with HTTP ${status}${code}: ${message}`;
}

function extractChatCompletionText(payload: OpenAiChatCompletionPayload): string {
	const outputParts: string[] = [];
	for (const choice of payload.choices ?? []) {
		const content = choice.message?.content;
		if (typeof content === "string") {
			outputParts.push(content);
			continue;
		}

		for (const part of content ?? []) {
			if (typeof part.text === "string") {
				outputParts.push(part.text);
			}
		}
	}

	return outputParts.join("\n");
}

function extractOpenAiStreamDelta(payload: OpenAiStreamPayload): string {
	if (typeof payload.delta === "string") {
		return payload.delta;
	}

	const outputParts: string[] = [];
	for (const content of payload.item?.content ?? []) {
		if (typeof content.text === "string") {
			outputParts.push(content.text);
		}
	}

	return outputParts.join("\n");
}

function parseOpenAiErrorPayload(text: string): OpenAiErrorPayload {
	try {
		const parsed = JSON.parse(text) as OpenAiErrorPayload;
		return parsed && typeof parsed === "object" ? parsed : {};
	} catch {
		return {};
	}
}

import { requestUrl } from "obsidian";
import { CodexAuthData } from "../settings-data";
import { isAbortError, LLM_CANCELED_MESSAGE, throwIfAborted } from "./abort";
import { CodexReasoningEffort, CodexServiceTier } from "./models";
import { CODEX_ORIGINATOR, CODEX_RESPONSES_URL, CODEX_VERSION, getCodexUserAgent } from "./codex-auth";
import { canUseFetchStreaming, readFetchSseStream, StreamingUnavailableError } from "./sse";
import { extractResponsesOutputText, ResponsesOutputPayload } from "./responses-payload";
import {
	ApiUsagePayload,
	buildEstimatedUsage,
	buildProgress,
	estimateInputTokens,
	LlmProgressCallback,
	LlmTokenUsage,
	usageFromApi,
} from "./token-usage";

interface CodexErrorPayload {
	detail?: string;
	error?: {
		message?: string;
		type?: string;
		code?: string;
	};
}

interface CodexSsePayload {
	type?: string;
	delta?: string;
	usage?: ApiUsagePayload;
	item?: {
		content?: Array<{
			text?: string;
			type?: string;
		}>;
	};
	response?: ResponsesOutputPayload;
}

export interface CodexRequestOptions {
	reasoningEffort: CodexReasoningEffort;
	serviceTier: CodexServiceTier;
	instructions?: string;
	onProgress?: LlmProgressCallback;
	signal?: AbortSignal;
}

export interface CodexTextResponse {
	text: string;
	usage: LlmTokenUsage;
}

export class CodexRequestError extends Error {
	status: number;

	constructor(status: number, message: string) {
		super(message);
		this.name = "CodexRequestError";
		this.status = status;
	}
}

export async function requestCodexText(
	model: string,
	prompt: string,
	auth: CodexAuthData,
	options: CodexRequestOptions,
): Promise<CodexTextResponse> {
	throwIfAborted(options.signal);
	const inputTokens = estimateInputTokens(options.instructions, prompt);
	options.onProgress?.({
		...buildEstimatedUsage(inputTokens, ""),
		phase: "uploading",
	});

	if (options.onProgress && canUseFetchStreaming()) {
		try {
			return await requestCodexTextStreaming(model, prompt, auth, options, inputTokens);
		} catch (error) {
			if (!(error instanceof StreamingUnavailableError)) {
				throw error;
			}
		}
	}

	return requestCodexTextBuffered(model, prompt, auth, options, inputTokens);
}

async function requestCodexTextBuffered(
	model: string,
	prompt: string,
	auth: CodexAuthData,
	options: CodexRequestOptions,
	inputTokens: number,
): Promise<CodexTextResponse> {
	throwIfAborted(options.signal);
	options.onProgress?.({
		...buildEstimatedUsage(inputTokens, ""),
		phase: "waiting",
	});

	const response = await requestUrl({
		url: CODEX_RESPONSES_URL,
		method: "POST",
		contentType: "application/json",
		headers: {
			Accept: "text/event-stream",
			Authorization: `Bearer ${auth.accessToken}`,
			"ChatGPT-Account-ID": auth.accountId,
			"User-Agent": getCodexUserAgent(),
			originator: CODEX_ORIGINATOR,
			version: CODEX_VERSION,
		},
		body: JSON.stringify(buildCodexRequestBody(model, prompt, options)),
		throw: false,
	});
	throwIfAborted(options.signal);

	if (response.status < 200 || response.status >= 300) {
		throw new CodexRequestError(response.status, formatCodexError(response.status, response.text, response.json as CodexErrorPayload));
	}

	const result = extractCodexSseOutput(response.text, inputTokens, options.onProgress);
	options.onProgress?.(buildProgress("completed", inputTokens, result.text, result.usage));
	return result;
}

async function requestCodexTextStreaming(
	model: string,
	prompt: string,
	auth: CodexAuthData,
	options: CodexRequestOptions,
	inputTokens: number,
): Promise<CodexTextResponse> {
	let response: Response;
	try {
		response = await globalThis.fetch(CODEX_RESPONSES_URL, {
			method: "POST",
			headers: {
				Accept: "text/event-stream",
				Authorization: `Bearer ${auth.accessToken}`,
				"ChatGPT-Account-ID": auth.accountId,
				"Content-Type": "application/json",
				"User-Agent": getCodexUserAgent(),
				originator: CODEX_ORIGINATOR,
				version: CODEX_VERSION,
			},
			body: JSON.stringify(buildCodexRequestBody(model, prompt, options)),
			signal: options.signal,
		});
	} catch (error) {
		if (isAbortError(error) || options.signal?.aborted) {
			throw new Error(LLM_CANCELED_MESSAGE);
		}

		throw new StreamingUnavailableError(error instanceof Error ? error.message : "Streaming request failed.");
	}

	if (!response.ok) {
		const text = await response.text();
		throw new CodexRequestError(response.status, formatCodexError(response.status, text, parseCodexErrorPayload(text)));
	}

	const result = readCodexStream(response, inputTokens, options);
	return result;
}

function formatCodexError(status: number, text: string, payload: CodexErrorPayload): string {
	const message = payload.detail || payload.error?.message || text || "Codex returned an error.";
	return `Codex request failed with HTTP ${status}: ${message}`;
}

function extractCodexSseOutput(
	text: string,
	inputTokens: number,
	onProgress?: LlmProgressCallback,
): CodexTextResponse {
	const completedItems: string[] = [];
	const deltas: string[] = [];
	const events = text.split(/\n\n+/);
	let usage: LlmTokenUsage | undefined;

	for (const event of events) {
		const data = event
			.split(/\r?\n/)
			.filter((line) => line.startsWith("data:"))
			.map((line) => line.slice(5).trimStart())
			.join("\n");

		if (!data || data === "[DONE]") {
			continue;
		}

		try {
			const payload = JSON.parse(data) as CodexSsePayload;
			if (typeof payload.delta === "string") {
				deltas.push(payload.delta);
				onProgress?.(buildProgress("streaming", inputTokens, deltas.join("")));
			}

			const itemText = extractOutputItemText(payload);
			if (itemText) {
				completedItems.push(itemText);
			}

			const responseText = payload.response ? extractResponsesOutputText(payload.response) : "";
			if (responseText) {
				completedItems.push(responseText);
			}

			usage = usageFromApi(payload.response?.usage ?? payload.usage) ?? usage;
		} catch {
			// Ignore malformed event frames and keep scanning the completed stream.
		}
	}

	const outputText = completedItems[completedItems.length - 1] ?? deltas.join("");
	return {
		text: outputText,
		usage: usage ?? buildEstimatedUsage(inputTokens, outputText),
	};
}

async function readCodexStream(
	response: Response,
	inputTokens: number,
	options: CodexRequestOptions,
): Promise<CodexTextResponse> {
	let streamedText = "";
	let completedText = "";
	let usage: LlmTokenUsage | undefined;

	await readFetchSseStream(response, (data) => {
		throwIfAborted(options.signal);
		if (data === "[DONE]") {
			return;
		}

		const payload = JSON.parse(data) as CodexSsePayload;
		if (typeof payload.delta === "string") {
			streamedText += payload.delta;
			options.onProgress?.(buildProgress("streaming", inputTokens, streamedText));
		}

		const itemText = extractOutputItemText(payload);
		if (itemText) {
			completedText = itemText;
		}

		const responseText = payload.response ? extractResponsesOutputText(payload.response) : "";
		if (responseText) {
			completedText = responseText;
		}

		usage = usageFromApi(payload.response?.usage ?? payload.usage) ?? usage;
	});

	const text = completedText || streamedText;
	throwIfAborted(options.signal);
	const finalUsage = usage ?? buildEstimatedUsage(inputTokens, text);
	options.onProgress?.(buildProgress("completed", inputTokens, text, finalUsage));

	return {
		text,
		usage: finalUsage,
	};
}

function extractOutputItemText(payload: CodexSsePayload): string {
	const outputParts: string[] = [];

	for (const content of payload.item?.content ?? []) {
		if (typeof content.text === "string") {
			outputParts.push(content.text);
		}
	}

	return outputParts.join("\n");
}

function buildCodexRequestBody(model: string, prompt: string, options: CodexRequestOptions): Record<string, unknown> {
	return {
		model,
		instructions: options.instructions ?? "You are a concise assistant.",
		input: [
			{
				role: "user",
				content: [
					{
						type: "input_text",
						text: prompt,
					},
				],
			},
		],
		tools: [],
		tool_choice: "auto",
		parallel_tool_calls: false,
		reasoning: {
			effort: options.reasoningEffort,
			summary: "auto",
		},
		include: ["reasoning.encrypted_content"],
		store: false,
		service_tier: options.serviceTier === "default" ? undefined : options.serviceTier,
		stream: true,
	};
}

function parseCodexErrorPayload(text: string): CodexErrorPayload {
	try {
		const parsed = JSON.parse(text) as CodexErrorPayload;
		return parsed && typeof parsed === "object" ? parsed : {};
	} catch {
		return {};
	}
}

import assert from "node:assert/strict";
