test("appends a # Cards section when none exists", () => {
	const body = "# Article\n\nSource material.\n";
	const cards = "# Cards\n\n## New card\n{{c1::new}}";

	assert.equal(replaceOrAppendAnkiCardsSection(body, cards), [
